import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Implements Dijkstra's algorithm to find the shortest path in a weighted directed graph."""

    priority_queue = [(0, start)]
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    path = []
    current = end
    if distances[end] == float('inf'):
        return (float('inf'), path)

    while current is not None:
        path.append(current)
        current = previous_nodes[current]

    path.reverse()
    return distances[end], path

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Implements the Bellman-Ford algorithm to find the shortest path in a weighted directed graph."""

    vertices = list(graph.keys())
    distances = {vertex: float('inf') for vertex in vertices}
    distances[start] = 0
    predecessors = {vertex: None for vertex in vertices}

    # Relax edges repeatedly
    for _ in range(len(vertices) - 1):
        for u in vertices:
            for v, weight in graph.get(u, []):
                if distances[u] + weight < distances[v]:
                    distances[v] = distances[u] + weight
                    predecessors[v] = u

    # Check for negative-weight cycles
    for u in vertices:
        for v, weight in graph.get(u, []):
            if distances[u] + weight < distances[v]:
                return (float('-inf'), [])  # Negative cycle found

    path = []
    if distances[end] == float('inf'):
        return (float('inf'), path)

    current = end
    while current is not None:
        path.append(current)
        current = predecessors[current]

    path.reverse()
    return distances[end], path

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Implements the A* algorithm to find the shortest path in a weighted directed graph."""

    def heuristic(node: str) -> float:
