    open_set = {start}
    g_costs = {node: float('inf') for node in graph}
    g_costs[start] = 0
    f_costs = {node: float('inf') for node in graph}
    f_costs[start] = heuristic(start)
    came_from = {}

    while open_set:
        current = min(open_set, key=lambda node: f_costs[node])
        if current == end:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            path.reverse()
            return g_costs[end], path

        open_set.remove(current)

        for neighbor, weight in graph.get(current, []):
            tentative_g_cost = g_costs[current] + weight
            if tentative_g_cost < g_costs[neighbor]:
                came_from[neighbor] = current
                g_costs[neighbor] = tentative_g_cost
                f_costs[neighbor] = tentative_g_cost + heuristic(neighbor)
                open_set.add(neighbor)

    return float('inf'), []

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Implements the Floyd-Warshall algorithm to find the shortest path in a weighted directed graph."""

    # Initialize distance matrix with infinity
    nodes = list(graph.keys())
    dist = {node: {n: float('inf') for n in nodes} for node in nodes}
    next_node = {node: {n: None for n in nodes} for node in nodes}

    # Set distance to self as 0 and initialize edges
    for node in nodes:
        dist[node][node] = 0
        for neighbor, weight in graph.get(node, []):
            dist[node][neighbor] = weight
            next_node[node][neighbor] = neighbor

    # Floyd-Warshall algorithm
    for k in nodes:
        for i in nodes:
            for j in nodes:
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
                    next_node[i][j] = next_node[i][k]

    # Reconstruct the path from start to end
    if dist[start][end] == float('inf'):
        return (float('inf'), [])

    path = []
    current = start
    while current is not None:
        path.append(current)
        if current == end:
            break
        current = next_node[current][end]

    return dist[start][end], path

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Implements the Breadth-First Search (BFS) approach with edge weights considered, using a queue for exploration."""

    from collections import deque
    import sys

    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    queue = deque([start])
    predecessors = {node: None for node in graph}

    while queue:
        current = queue.popleft()

        for neighbor, weight in graph[current]:
            distance = distances[current] + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current
                queue.append(neighbor)

    path = []
    if distances[end] == float('inf'):
        return (float('inf'), path)

    current = end
    while current is not None:
        path.append(current)
        current = predecessors[current]

    path.reverse()
    return distances[end], path
